def load() -> pd.DataFrame:
    import numpy as np
    from pathlib import Path

    p = Path('data/astronomy/input/mock_tiegcm_grid_sept2019.npz')
    npz = np.load(p, allow_pickle=True)
    rows = []
    for k in npz.files:
        a = npz[k]
        rows.append({
            'key': k,
            'dtype': str(a.dtype),
            'shape': str(a.shape),
            'ndim': int(a.ndim),
        })
    return pd.DataFrame(rows).sort_values('key').reset_index(drop=True)

