def load() -> pd.DataFrame:
    import glob
    pats = [
        'data/astronomy/input/swarm/**/*.sp3',
        'data/astronomy/input/swarm/**/**/*.sp3',
        'data/astronomy/input/**/**/*.sp3',
    ]
    rows=[]
    for pat in pats:
        files=sorted(glob.glob(pat, recursive=True))
        rows.append({'pattern':pat,'n_files':len(files),'sample':files[:10]})
    return pd.DataFrame(rows)

