def process(sp3_list_sept) -> pd.DataFrame:
    import pandas as pd, glob, re
    from datetime import datetime

    # collect all Sept 2019 sp3 files (we trust list output but rebuild here)
    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*T*_0201/*.sp3'))
    rows = []
    epoch = None
    # SP3 columns are fixed-width; positions in km
    for fp in files:
        with open(fp, 'r') as f:
            for line in f:
                if not line:
                    continue
                if line.startswith('*'):
                    # *  2019 09 02 23 59 42.00000000
                    parts = line[1:].strip().split()
                    if len(parts) >= 6:
                        y, mo, d, hh, mm = map(int, parts[:5])
                        ss = float(parts[5])
                        epoch = datetime(y, mo, d, hh, mm, int(ss), int(round((ss-int(ss))*1e6)))
                    else:
                        epoch = None
                elif line.startswith('P') and epoch is not None:
                    sat = line[1:4].strip()  # e.g., 'A', or 'G01'
                    if sat != 'A':
                        continue
                    # x y z clock in km and microseconds; may have missing (999999.999999)
                    def parse_field(s):
                        try:
                            v = float(s)
                            if abs(v) > 9e5:
                                return None
                            return v
                        except:
                            return None
                    x = parse_field(line[4:18])
                    y = parse_field(line[18:32])
                    z = parse_field(line[32:46])
                    if x is None or y is None or z is None:
                        continue
                    rows.append((epoch, x, y, z))

    df = pd.DataFrame(rows, columns=['epoch','x_km','y_km','z_km'])
    if df.empty:
        return df

    df = df.sort_values('epoch')
    df = df[(df['epoch'] >= pd.Timestamp('2019-09-02')) & (df['epoch'] < pd.Timestamp('2019-09-30'))]
    return df.reset_index(drop=True)

