    import pandas as pd, glob
    from datetime import datetime

    files = []
    if isinstance(sp3_list_sept, pd.DataFrame) and not sp3_list_sept.empty:
        # stored as string repr of list; safer to glob again using known pattern
        files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*T*_0201/*.sp3'))
    else:
        files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*T*_0201/*.sp3'))

    rows = []
    epoch = None

    def parse_epoch(line: str):
        # *  2019 09 02 23 59 42.00000000
        parts = line[1:].strip().split()
        if len(parts) < 6:
            return None
        y, mo, d, hh, mm = map(int, parts[:5])
        ss = float(parts[5])
        sec = int(ss)
        usec = int(round((ss - sec) * 1e6))
        if usec == 1000000:
            sec += 1
            usec = 0
        return datetime(y, mo, d, hh, mm, sec, usec)

    def parse_field(s):
        try:
            v = float(s)
            if abs(v) > 9e5:  # missing marker like 999999.999999
                return None
            return v
        except:
            return None

    for fp in files:
        # use pandas to read file without direct open()
        try:
            lines = pd.read_csv(fp, header=None, sep='\n', engine='python', dtype=str)[0].tolist()
        except Exception:
            # fallback: fixed-width read into single column
            lines = pd.read_fwf(fp, header=None, widths=[200], dtype=str)[0].tolist()

        for line in lines:
