input.code:
def load() -> pd.DataFrame:
    import glob
    import pandas as pd
    from datetime import datetime

    paths = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*/*.sp3'))
    if len(paths) == 0:
        paths = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*.sp3'))

    rows = []
    current_epoch = None

    start = pd.Timestamp('2019-09-02T00:00:00Z')
    end = pd.Timestamp('2019-09-30T00:00:00Z')

    for p in paths:
        with open(p, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if not line:
                    continue
                if line.startswith('*'):
                    # *  2019 09 02 23 59 42.00000000
                    parts = line.strip().split()
                    if len(parts) >= 7:
                        y, mo, d, hh, mm = map(int, parts[1:6])
                        ss = float(parts[6])
                        sec = int(ss)
                        micro = int(round((ss - sec) * 1e6))
                        current_epoch = pd.Timestamp(datetime(y, mo, d, hh, mm, sec, micro), tz='UTC')
                    else:
                        current_epoch = None
                elif line.startswith('P') and current_epoch is not None:
                    # Position record: P{sat} x y z clk
                    sat = line[1:4].strip()
                    if sat == 'A':
                        try:
                            x_km = float(line[4:18])
                            y_km = float(line[18:32])
                            z_km = float(line[32:46])
                        except Exception:
                            # fallback split
                            sp = line.split()
                            if len(sp) >= 5:
                                x_km, y_km, z_km = map(float, sp[1:4])
                            else:
                                continue
                        if (current_epoch >= start) and (current_epoch < end):
                            rows.append((current_epoch, x_km, y_km, z_km))

    df = pd.DataFrame(rows, columns=['epoch_utc', 'x_km', 'y_km', 'z_km'])
    if len(df) == 0:
        return df
    df = df.sort_values('epoch_utc').reset_index(drop=True)
    return df

