def load() -> pd.DataFrame:
    import glob
    import pandas as pd
    from datetime import datetime

    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*/*.sp3'))
    rows = []
    t0 = pd.Timestamp('2019-09-02T00:00:00Z')
    t1 = pd.Timestamp('2019-09-30T00:00:00Z')

    cur_t = None
    for path in files:
        with open(path, 'r') as f:
            for line in f:
                if not line:
                    continue
                if line.startswith('*'):
                    # *  2019 09 02 23 59 42.00000000
                    parts = line.strip().split()
                    if len(parts) >= 7:
                        y, mo, d, hh, mm = map(int, parts[1:6])
                        sec = float(parts[6])
                        ss = int(sec)
                        us = int(round((sec-ss)*1e6))
                        cur_t = pd.Timestamp(datetime(y, mo, d, hh, mm, ss, us), tz='UTC')
                    continue
                if line.startswith('PA') and cur_t is not None:
                    # PA SVR A??: Actually SP3 uses 'P' followed by sat id, e.g. 'PG01'
                    # Swarm-A appears as 'PA' (two-char id) in these files.
                    # Format: P{sat} x y z clock
                    sat = line[1:4].strip()  # may be 'A' or 'A  '
                    if sat.startswith('A') or sat == 'A':
                        try:
                            x = float(line[4:18])
                            y = float(line[18:32])
                            z = float(line[32:46])
                        except Exception:
                            # fallback split
                            parts = line.split()
                            if len(parts) >= 5:
                                x, y, z = map(float, parts[1:4])
                            else:
                                continue
                        if t0 <= cur_t < t1:
                            rows.append((cur_t, x, y, z, path))
    df = pd.DataFrame(rows, columns=['epoch','x_km','y_km','z_km','source_file'])
    return df.sort_values('epoch').reset_index(drop=True)

