    t1 = pd.Timestamp('2019-09-30T00:00:00Z')

    rows = []
    cur_t = None
    for p in paths:
        # only September 2019 files by path
        if '201909' not in p:
            continue
        with open(p, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if not line:
                    continue
                if line.startswith('*'):
                    # *  2019 09 02 23 59 42.00000000
                    parts = line.strip().split()
                    if len(parts) >= 7:
                        y, mo, d, hh, mm = map(int, parts[1:6])
                        ss = float(parts[6])
                        s_int = int(ss)
                        us = int(round((ss - s_int) * 1e6))
                        cur_t = pd.Timestamp(datetime(y, mo, d, hh, mm, s_int, us), tz='UTC')
                    else:
                        cur_t = None
                elif line.startswith('PA') and cur_t is not None:
                    # PA x y z clock
                    # values in km
                    parts = line.strip().split()
                    if len(parts) >= 5:
                        try:
                            x = float(parts[1]); y = float(parts[2]); z = float(parts[3])
                        except:
                            continue
                        if (cur_t >= t0) and (cur_t < t1):
                            rows.append((cur_t, x, y, z))
    if len(rows) == 0:
        return pd.DataFrame(columns=['epoch','x_km','y_km','z_km'])
    df = pd.DataFrame(rows, columns=['epoch','x_km','y_km','z_km']).drop_duplicates(subset=['epoch']).sort_values('epoch')
    return df

