def load() -> pd.DataFrame:
    import glob
    import pandas as pd
    import numpy as np

    paths = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*/*.sp3'))
    # fallback: one level without extra folder
    if len(paths) == 0:
        paths = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*.sp3'))

    rows = []
    cur_t = None

    def parse_epoch(line: str):
        # *  2019 09 02 23 59 42.00000000
        parts = line[1:].split()
        if len(parts) < 6:
            return None
        y, mo, d, hh, mm = map(int, parts[:5])
        sec = float(parts[5])
        whole = int(sec)
        frac = sec - whole
        us = int(round(frac * 1e6))
        return pd.Timestamp(y, mo, d, hh, mm, whole, us, tz='UTC')

    def parse_p(line: str):
        # P<sat> x y z clk  (km, km, km)
        # sat could be 'A' or 'A ' etc; robustly take first 3 after P
        sat = line[1:4].strip()  # e.g., 'A', 'G01', etc.
        nums = line[4:].split()
        if len(nums) < 3:
            return sat, None
        try:
            x, y, z = map(float, nums[:3])
        except Exception:
            return sat, None
        return sat, (x, y, z)

    for pth in paths:
        with open(pth, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if not line:
                    continue
                if line.startswith('*'):
                    cur_t = parse_epoch(line)
                elif line.startswith('P') and cur_t is not None:
                    sat, xyz = parse_p(line)
                    if xyz is None:
                        continue
                    # Swarm-A is usually satellite 'A' in these files
                    if sat == 'A' or sat.endswith('A'):
                        rows.append((cur_t, xyz[0], xyz[1], xyz[2]))

    df = pd.DataFrame(rows, columns=['epoch_utc', 'x_km', 'y_km', 'z_km'])
    if len(df) == 0:
        return df

    # Filter to Sep 2-29 inclusive (i.e., < Sep 30)
    start = pd.Timestamp('2019-09-02T00:00:00Z')
    end = pd.Timestamp('2019-09-30T00:00:00Z')
    df = df[(df['epoch_utc'] >= start) & (df['epoch_utc'] < end)].sort_values('epoch_utc').reset_index(drop=True)
    return df

