def load() -> pd.DataFrame:
    import glob
    import pandas as pd
    from datetime import datetime

    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909??T????_201909??T????_0201/*.sp3'))
    rows = []
    t = None
    for fp in files:
        with open(fp, 'r', encoding='utf-8', errors='ignore') as f:
            for line in f:
                if not line:
                    continue
                if line.startswith('*'):
                    # *  yyyy mm dd hh mm ss.ssssssss
                    parts = line.strip().split()
                    if len(parts) >= 7:
                        y, mo, d, hh, mm = map(int, parts[1:6])
                        sec = float(parts[6])
                        isec = int(sec)
                        usec = int(round((sec - isec) * 1e6))
                        t = datetime(y, mo, d, hh, mm, isec, usec)
                elif line.startswith('P') and t is not None:
                    # P{sat} x y z clock ... ; in km for SP3
                    sat = line[1:4].strip()
                    if sat == 'A':
                        # fixed width columns per SP3: x(4:18) y(18:32) z(32:46)
                        try:
                            x = float(line[4:18])
                            y = float(line[18:32])
                            z = float(line[32:46])
                        except Exception:
                            # fallback split
                            parts = line.strip().split()
                            if len(parts) >= 4:
                                x, y, z = map(float, parts[1:4])
                            else:
                                continue
                        rows.append({'epoch_utc': t, 'x_km': x, 'y_km': y, 'z_km': z, 'file': fp})

    df = pd.DataFrame(rows)
    if df.empty:
        return df

    df = df.sort_values('epoch_utc')
    start = pd.Timestamp('2019-09-02T00:00:00')
    end = pd.Timestamp('2019-09-30T00:00:00')
    df = df[(df['epoch_utc'] >= start) & (df['epoch_utc'] < end)]
    return df.reset_index(drop=True)

