def load() -> pd.DataFrame:
    import pandas as pd, glob, re
    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*/*.sp3'))
    if not files:
        files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*.sp3'))
    # filter 20190902..20190929 by folder/file name
    keep=[]
    for fp in files:
        m=re.search(r'__201909(\d\d)T', fp)
        if m:
            day=int(m.group(1))
            if 2 <= day <= 29:
                keep.append(fp)
    return pd.DataFrame({'path':keep})

def load() -> pd.DataFrame:
    import pandas as pd, glob
    files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*/*.sp3'))
    if not files:
        files = sorted(glob.glob('data/astronomy/input/swarm/POD/SW_OPER_SP3ACOM_2__201909*/*.sp3'))
    dfs = []
    for fp in files:
        try:
            df = pd.read_fwf(
                fp,
                header=None,
                widths=[1,3,14,14,14,14],
                names=['rec','sv','x_km','y_km','z_km','clk'],
                dtype=str,
            )
        except Exception:
            continue
        df['path'] = fp
        dfs.append(df)
    if not dfs:
        return pd.DataFrame(columns=['rec','sv','x_km','y_km','z_km','clk','path'])
    out = pd.concat(dfs, ignore_index=True)
    return out

def process(sp3_points) -> pd.DataFrame:
    import pandas as pd, numpy as np

    df = sp3_points.copy()

    # Identify epoch lines and parse datetime from x_km/y_km columns as captured by sp3_points loader
    ep = df[df['rec'] == '*'].copy()
    if ep.empty:
        return pd.DataFrame(columns=['epoch_utc','x_km','y_km','z_km'])

    # In the fixed-width parsing used, for '*' lines:
    # sv has some token, x_km holds like '2019 09 03 00 00', y_km holds like '00.00000000'
    # We'll reconstruct full timestamp from x_km and y_km.
    def parse_star(row):
        try:
            # x_km includes year month day hour minute
            parts = str(row['x_km']).strip().split()
            if len(parts) >= 5:
                y, mo, d, hh, mm = map(int, parts[:5])
            else:
                # fallback: try splitting original line stored across columns
                return pd.NaT
            ss = float(str(row['y_km']).strip())
            return pd.Timestamp(year=y, month=mo, day=d, hour=hh, minute=mm, tz='UTC') + pd.to_timedelta(ss, unit='s')
        except Exception:
            return pd.NaT

    ep['epoch_utc'] = ep.apply(parse_star, axis=1)
    ep = ep.dropna(subset=['epoch_utc'])
    # epoch index within each file
    ep['epoch_idx'] = ep.groupby('path').cumcount()
    ep = ep[['path','epoch_idx','epoch_utc']]

    # Position lines for L47
    pos = df[(df['rec'] == 'P') & (df['sv'] == 'L47')].copy()
    if pos.empty:
        return pd.DataFrame(columns=['epoch_utc','x_km','y_km','z_km'])
    pos['epoch_idx'] = pos.groupby('path').cumcount()

    # Convert coordinates to numeric
    for c in ['x_km','y_km','z_km']:
        pos[c] = pd.to_numeric(pos[c], errors='coerce')
    pos = pos.dropna(subset=['x_km','y_km','z_km'])

    merged = pos.merge(ep, on=['path','epoch_idx'], how='inner')
    if merged.empty:
        return pd.DataFrame(columns=['epoch_utc','x_km','y_km','z_km'])

    # Filter time window
    start = pd.Timestamp('2019-09-02T00:00:00Z')
    end = pd.Timestamp('2019-09-30T00:00:00Z')
    merged = merged[(merged['epoch_utc'] >= start) & (merged['epoch_utc'] < end)].copy()
    merged = merged.sort_values('epoch_utc')

    out = merged[['epoch_utc','x_km','y_km','z_km']].reset_index(drop=True)
    # make naive utc
    out['epoch_utc'] = out['epoch_utc'].dt.tz_convert(None)
    return out

